/// <summary>
/// Contract class for Rebate line
/// </summary>
[DataContractAttribute]
public class METTAMRebateLineContract
{
    LineNum lineNum;
    TAMRebateId tamRebateId;
    TAMRebateDeductionAmount tamRebateDeductionAmount;
    TAMRebateMethod tamRebateMethod;
    TAMRebateFrom tamRebateFrom;
    TAMRebateLimit tamRebateLimit;

    const str agreementLineNumber = "agreementLineNumber";
    const str agreementNumber = "agreementNumber";
    const str rebateAmount = "RebateAmount";
    const str rebateCalculationMethod = "rebateCalculationMethod";
    const str rebateValidFromQuantityAmount = "rebateValidFromQuantityAmount";
    const str rebateValidToQuantityAmount = "rebateValidToQuantityAmount";

}

Method.Source:
/// <summary>
/// Line number
/// </summary>
/// <param name = "_lineNum">LineNum</param>
/// <returns>LineNum</returns>
[DataMemberAttribute(identifierStr(agreementLineNumber))]
public LineNum parmAgreementLineNumber(LineNum _lineNum = lineNum)
{
    lineNum = _lineNum;
    return lineNum;
}

/// <summary>
/// Agreement number
/// </summary>
/// <param name = "_tamRebateId">TAMRebateId</param>
/// <returns>TAMRebateId</returns>
[DataMemberAttribute(identifierStr(agreementNumber))]
public TAMRebateId parmAgreementNumber(TAMRebateId _tamRebateId = tamRebateId)
{
    tamRebateId = _tamRebateId;
    return tamRebateId;
}

