[DataMemberAttribute(identifierStr(rebateCalculationMethod))]
public TAMRebateMethod parmRebateCalculationMethod(TAMRebateMethod _tamRebateMethod = tamRebateMethod)
{
    tamRebateMethod = _tamRebateMethod;
    return tamRebateMethod;
}

/// <summary>
/// From quantity
