[DataMemberAttribute(identifierStr(rebateValidFromQuantityAmount))]
public TAMRebateFrom parmRebateValidFromQuantityAmount(TAMRebateFrom _tamRebateFrom = tamRebateFrom)
{
    tamRebateFrom = _tamRebateFrom;
    return tamRebateFrom;
}

/// <summary>
